using Captovix;
using System.IO;
using System.Security.Cryptography;
using System.Windows;
using System.Windows.Media.Imaging;
internal static class Program
{
 static int n;static void Check(bool ok,string text){if(!ok)throw new Exception(text);n++;Console.WriteLine("PASS: "+text);}
 [STAThread]static int Main(){MediaItem? media=null;var folder=Path.Combine(Path.GetTempPath(),"Captovix-M3-"+Guid.NewGuid().ToString("N"));Directory.CreateDirectory(folder);try{
 const int w=320,h=180;var data=Enumerable.Repeat((byte)255,w*h*4).ToArray();for(int y=36;y<62;y++)for(int x=25;x<80;x++){int p=(y*w+x)*4;data[p]=40;data[p+1]=40;data[p+2]=220;}for(int y=40;y<56;y++)for(int x=112;x<119;x++){int p=(y*w+x)*4;data[p]=data[p+1]=data[p+2]=0;}
 var image=ImageTransfer.Bitmap(w,h,data);string path=Path.Combine(folder,"form.png");ImageTransfer.Save(image,path);media=new(){Id=Guid.NewGuid().ToString("N"),FilePath=path};var session=DocumentStore.Load(media,image,out _);var a=MockupStudio.Create(new(20,30,120,40),new(0,0,w,h),new("#FFFFFF","#DC2828","#FFFFFF",1));a.Mockup!.Type=MockupKind.Button;a.Text="";session.Change(d=>MockupStudio.Apply(d,a));DocumentStore.Save(media,session,image);var oldSidecar=File.ReadAllBytes(DocumentStore.EditPath(media.Id));
 var surface=new EditorSurface{Tool=EditorTool.Select,SnapEnabled=false};surface.Load(image,session);surface.SetZoom(1);surface.SelectIds([a.Id]);surface.PointerDown(new(45,50));surface.PointerMove(new(180,100));surface.PointerUp(new(180,100));Check(session.Document.Recoveries.Count==1&&session.Document.Annotations[0].Mockup!.RecoveryId!=null,"Native editor gesture detaches source mask when moving M2 object");
 var moved=ImageTransfer.Bgra(surface.Flatten());bool oldRemoved=true,neighbor=true;for(int y=36;y<62;y++)for(int x=25;x<80;x++){int p=(y*w+x)*4;oldRemoved &= moved[p]==255&&moved[p+1]==255&&moved[p+2]==255;}for(int y=40;y<56;y++)for(int x=112;x<119;x++){int p=(y*w+x)*4;neighbor &= moved[p]==0&&moved[p+1]==0&&moved[p+2]==0;}Check(oldRemoved,"Moving button leaves flat restored background at original location");Check(neighbor,"Neighbor component inside loose selection remains pixel-identical");Check(ImageTransfer.Bgra(image).SequenceEqual(data),"Editor gesture never changes original PNG bitmap");
 string afterMove=session.Document.Serialize();session.Undo();Check(session.Document.Recoveries.Count==0,"Undo movement restores legacy state atomically");session.Redo();surface.Refresh();Check(session.Document.Serialize()==afterMove,"Redo movement restores exact mask/body state");
 var originalBounds=session.Document.Recoveries[0].Bounds;session.Change(d=>AnnotationEditing.Transform(d.Annotations[0],d.Annotations[0].Copy(),new(d.Annotations[0].Left,d.Annotations[0].Top,d.Annotations[0].Width,d.Annotations[0].Height),new(160,80,145,70)));surface.Refresh();Check(session.Document.Recoveries.Count==1&&session.Document.Recoveries[0].Bounds==originalBounds,"Resize does not grow, move or duplicate old-location recovery");
 surface.SelectIds([a.Id]);surface.DeleteSelected();Check(session.Document.Annotations.Count==0&&session.Document.Recoveries.Count==1,"Deleting element keeps independent restoration");var deleted=ImageTransfer.Bgra(surface.Flatten());Check(deleted[(45*w+40)*4]==255&&deleted[(45*w+114)*4]==0,"Exact export includes recovery even with zero annotations and preserves neighbor");var cropped=session.Document.Snapshot();cropped.Crop=new(150,0,170,180);cropped.Appearance.DrawOutsideImage=true;cropped.Appearance.ExtendLeft=200;cropped.Appearance.BackgroundColor="#00FFFF";var cropImage=EditorRenderer.Render(image,cropped);var mapped=new ImageLayout(cropped.Viewport,cropped.Appearance).ToOutput(40,45);var cropPixels=ImageTransfer.Bgra(cropImage);int colorAt=((int)mapped.Y*cropImage.PixelWidth+(int)mapped.X)*4;Check(cropPixels[colorAt]==255&&cropPixels[colorAt+1]==255&&cropPixels[colorAt+2]==0,"Old-region recovery cannot paint into padding outside a cropped viewport");var sample=ImageTransfer.Bgra(EditorRenderer.RecoveredSampling(image,session.Document));Check(sample[(45*w+40)*4]==255&&sample[(45*w+114)*4]==0,"Effects sample restored background rather than hidden old button");
 DocumentStore.Save(media,session,image);Check(File.ReadAllBytes(DocumentStore.EditPath(media.Id)+".pre-v1.40.bak").SequenceEqual(oldSidecar),"Schema20 autosave preserves exact prior sidecar backup");var reopened=Task.Run(()=>DocumentStore.Load(media,image,out _)).GetAwaiter().GetResult();Check(reopened.Document.Recoveries.Count==1&&ImageTransfer.Bgra(EditorRenderer.Render(image,reopened.Document)).SequenceEqual(deleted),"Background reopen retains deleted-button restoration pixel-for-pixel");string project=Path.Combine(folder,"m3.captovix");CompositionProject.Save(project,ImageTransfer.Png(image),session.Document);var loaded=CompositionProject.Load(project);Check(loaded.Document.Version==20&&loaded.Document.Recoveries.Count==1,"Portable project persists independent mask/history result");
 Console.WriteLine(n+" M3 Windows render/gesture/persistence checks passed. Physical shortcut/editor/layout/capture and DPI acceptance remains separate.");return 0;
 }catch(Exception ex){Console.Error.WriteLine(ex);return 1;}finally{StaImageWorker.Stop();if(media!=null){foreach(var s in new[]{"",".bak",".pre-v1.13.bak",".pre-v1.38.bak",".pre-v1.39.bak",".pre-v1.40.bak"})File.Delete(DocumentStore.EditPath(media.Id)+s);File.Delete(DocumentStore.ThumbnailPath(media.Id));}Directory.Delete(folder,true);}}
}
